import{_ as p,a0 as i,w as l,s as u,ao as e,I as o,x as n,a1 as a,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"管理 crontab 的開源工具 | LCTT x X-CMD","titleTemplate":false,"description":"管理 crontab 的開源工具 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"管理 crontab 的開源工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"管理 crontab 的開源工具 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220506 My favorite open source tool for using crontab","title":"管理 crontab 的開源工具","tag":"202205","desc":""},"relativePath":"202205/20220506 My favorite open source tool for using crontab.md","filePath":"[post].md"}'),b={name:"202205/20220506 My favorite open source tool for using crontab.md"};function d(m,t,f,g,T,c){const r=i("Link");return l(),u("div",null,[t[27]||(t[27]=e('<h1 id="管理-crontab-的開源工具" tabindex="-1">管理 crontab 的開源工具 <a class="header-anchor" href="#管理-crontab-的開源工具" aria-label="Permalink to “管理 crontab 的開源工具”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/16/100309tw6wgx3sss36wl6r.jpg" alt=""></p><blockquote><p>crontab-ui 是一個用 Node.js 編寫的 Web 前端，幫助管理 crontab 文件。</p></blockquote><p><em>自動化是目前的一個熱門話題。在我作為網站可靠性工程師（SRE）的日常工作中，我的部分職責是將盡可能多的重複性任務自動化。但是，有多少人在我們的日常非工作生活中這樣做呢？今年，我專注於將勞作自動化，以便我們可以專注於重要的事情。</em></p><p>作為一個初出茅廬的系統管理員，我最早了解的東西之一是 “cron”。cron 被廣泛用於做一些事情，如輪換日誌、啓動和停止服務、運行程序作業等等。它在幾乎所有的 Unix 和 Linux 系統中都可用，而且是我認識的每個系統管理員用來幫助管理服務和服務器的東西。cron 可以自動運行任何控制台應用或腳本，這使得它非常、非常靈活。</p><blockquote><p>LCTT 譯註：CRON 是 “Command Run On” 的縮寫，即在某個時間運行命令。</p></blockquote><p><img src="https://opensource.com/sites/default/files/2022-04/Day01-1.png" alt="Image of a Crontab"></p><p>我用 cron 來獲取電子郵件，運行過濾程序，確保服務正在運行，與 Habitica 等在線遊戲互動等。</p><h3 id="以傳統方式使用-cron" tabindex="-1">以傳統方式使用 cron <a class="header-anchor" href="#以傳統方式使用-cron" aria-label="Permalink to “以傳統方式使用 cron”">​</a></h3>',9)),o("p",null,[t[1]||(t[1]=n("要開始使用 cron，你可以簡單地在命令列輸入 ",-1)),t[2]||(t[2]=o("code",null,"crontab -e",-1)),t[3]||(t[3]=n("，啓動一個打開了當前 ",-1)),t[4]||(t[4]=o("code",null,"crontab",-1)),t[5]||(t[5]=n("（“cron table” 的縮寫）文件的編輯器（如果你以 root 身份這樣做，你訪問的是系統 crontab）。這是保存作業計劃的地方，記錄了何時運行。David Both 已經寫了 ",-1)),a(r,{href:"https://opensource.com/article/17/11/how-use-cron-linux"},{default:s(()=>[...t[0]||(t[0]=[n("大量",-1)])]),_:1}),t[6]||(t[6]=n(" 關於該文件的格式和如何使用它的文章，所以我不打算在這裏介紹。我要説的是，對於新用户來説，這可能有點嚇人，而且設置時間有點痛苦。",-1))]),t[28]||(t[28]=o("h3",{id:"介紹-crontab-ui",tabindex:"-1"},[n("介紹 crontab-ui "),o("a",{class:"header-anchor",href:"#介紹-crontab-ui","aria-label":"Permalink to “介紹 crontab-ui”"},"​")],-1)),o("p",null,[t[8]||(t[8]=n("有一些奇妙的工具可以幫助解決這個問題。我最喜歡的是 ",-1)),a(r,{href:"https://opensource.com/%5Bhttps%3A//github.com/alseambusher/crontab-ui%5D%28https%3A//github.com/alseambusher/crontab-ui%29"},{default:s(()=>[...t[7]||(t[7]=[n("crontab-ui",-1)])]),_:1}),t[9]||(t[9]=n("，這是一個用 Node.js 編寫的 Web 前端，可以幫助管理 crontab 文件。為了安裝和啓動 ",-1)),t[10]||(t[10]=o("code",null,"crontab-ui",-1)),t[11]||(t[11]=n(" 供個人使用，我使用了以下命令。",-1))]),t[29]||(t[29]=e(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 做個備份</span></span>
<span class="line"><span>crontab -l &gt; $HOME/crontab-backup</span></span>
<span class="line"><span># 安裝 Crontab UI</span></span>
<span class="line"><span>npm install -g crontab-ui</span></span>
<span class="line"><span># 創建本地資料庫目錄</span></span>
<span class="line"><span>mkdir $HOME/crontab-ui</span></span>
<span class="line"><span># 啓動 crontab-ui</span></span>
<span class="line"><span>CRON_DB_PATH=$HOME/crontab-ui crontab-ui</span></span></code></pre></div><p>完成這些後，只需將你的網頁瀏覽器指向 <code>http://localhost:8000</code>，你就會看到 crontab-ui 的網頁界面。要做的第一件事是點擊 “<ruby>從 Crontab 獲取<rt>Get from Crontab</rt></ruby>”，加載你可能有的任何現有作業。然後點擊“<ruby>備份<rt>Backup</rt></ruby>”，這樣你就可以回滾你所做的任何修改。</p><p><img src="https://opensource.com/sites/default/files/2022-04/Day01-2.png" alt="Image of Crontab-UI"></p><p>添加和編輯 cron 作業是非常簡單的。添加一個名稱，你想運行的完整命令，以及時間（使用 cron 語法），然後保存。另外，你還可以捕獲日誌，並設置將工作狀態郵寄到你選擇的電子郵箱。</p><p>完成後，點擊 “<ruby>保存到 Crontab<rt>Save to Crontab</rt></ruby>”。</p><p>我個人非常喜歡它的日誌記錄功能。有了 crontab-ui，你可以通過點擊一個按鈕來查看日誌，這在排除故障時非常有用。</p><p>我建議不要一直運行 crontab-ui，至少不要公開運行。雖然它確實具有一些基本的身份驗證功能，但它不應該暴露在你的本地機器之外。我不需要經常編輯我的 cron 作業，所以我可以按需啓動和停止它。</p><p>下次你需要編輯你的 crontab 時，可以試試 crontab-ui！</p><hr>`,9)),o("p",null,[t[13]||(t[13]=n("via: ",-1)),a(r,{href:"https://opensource.com/article/22/5/cron-crontab-ui"},{default:s(()=>[...t[12]||(t[12]=[n("https://opensource.com/article/22/5/cron-crontab-ui",-1)])]),_:1})]),o("p",null,[t[18]||(t[18]=n("作者：",-1)),a(r,{href:"https://opensource.com/users/ksonney"},{default:s(()=>[...t[14]||(t[14]=[n("Kevin Sonney",-1)])]),_:1}),t[19]||(t[19]=n(" 選題：",-1)),a(r,{href:"https://github.com/lkxed"},{default:s(()=>[...t[15]||(t[15]=[n("lkxed",-1)])]),_:1}),t[20]||(t[20]=n(" 譯者：",-1)),a(r,{href:"https://github.com/geekpi"},{default:s(()=>[...t[16]||(t[16]=[n("geekpi",-1)])]),_:1}),t[21]||(t[21]=n(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[17]||(t[17]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[24]||(t[24]=n("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[22]||(t[22]=[n("LCTT",-1)])]),_:1}),t[25]||(t[25]=n(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:s(()=>[...t[23]||(t[23]=[n("Linux中國",-1)])]),_:1}),t[26]||(t[26]=n(" 榮譽推出",-1))])])}const y=p(b,[["render",d]]);export{x as __pageData,y as default};
